mapper.select:

      	SELECT ta.*
      	FROM (
	    	SELECT /* + index_desc(b pk_product) */ ROWNUM rn, p.*
	    	FROM ( 
	    			SELECT  *
	    			FROM tbl_product
	    			WHERE expiration_date >= TRUNC(SYSDATE)
	    	  		AND expiration_date < TRUNC(SYSDATE) +5


			          AND product_price <= #{maxPrice}


                  ORDER BY
                  	  CASE WHEN #{sort} = 'price' THEN product_price END ASC,
                	  CASE WHEN #{sort} = 'createdDate' THEN product_no END DESC
	    	     ) p
	         ) ta
	    WHERE ta.rn > #{startRow}
	    AND   ta.rn <= #{startRow} + #{pageSize}
